name: Version Policy

on:
  pull_request:
    branches:
      - main

permissions:
  contents: read

jobs:
  check-version:
    # Keep the old required status check name, but stop requiring every PR to
    # spend a version number. Releases are cut from v* tags instead.
    name: "Check Version Bump"
    runs-on: ubuntu-latest
    steps:
      - name: "Checkout Code"
        uses: actions/checkout@v7

      - name: "Check package metadata"
        run: |
          PACKAGE_VERSION=$(jq -r .version frontend/package.json)
          LOCK_VERSION=$(jq -r .version frontend/package-lock.json)
          LOCK_ROOT_VERSION=$(jq -r '.packages[""].version' frontend/package-lock.json)
          PYPROJECT_VERSION=$(sed -n 's/^version = "\(.*\)"$/\1/p' backend/pyproject.toml | head -1)
          UV_LOCK_VERSION=$(grep -A1 '^name = "family-tree-backend"$' backend/uv.lock | sed -n 's/^version = "\(.*\)"$/\1/p')

          echo "PRs do not need to bump the app version."
          echo "Release tags must be named v<frontend package version>."
          echo "frontend/package.json:      $PACKAGE_VERSION"
          echo "frontend/package-lock.json: $LOCK_VERSION"
          echo "lock root package:          $LOCK_ROOT_VERSION"
          echo "backend/pyproject.toml:     $PYPROJECT_VERSION"
          echo "backend/uv.lock:            $UV_LOCK_VERSION"

          if [ "$PACKAGE_VERSION" != "$LOCK_VERSION" ] || [ "$PACKAGE_VERSION" != "$LOCK_ROOT_VERSION" ] \
            || [ "$PACKAGE_VERSION" != "$PYPROJECT_VERSION" ] || [ "$PACKAGE_VERSION" != "$UV_LOCK_VERSION" ]; then
            echo "Version metadata is out of sync across frontend/backend."
            echo "Run 'npm run bump:patch|minor|major' from frontend/ — it updates all four files."
            exit 1
          fi
=====GEN-CHANGELOG=====
/**
 * Generates frontend/src/data/changelog.json from the repo-root CHANGELOG.md.
 *
 * The generated JSON is intentionally ignored by Git. Frontend build and dev
 * lifecycles run this script before Vite so the app always displays the
 * changelog from the source revision being built.
 *
 * Usage (from frontend/):
 *   node scripts/gen-changelog.mjs
 */

import { promises as fs } from "fs";
import path from "path";
import { fileURLToPath } from "url";
import { parseChangelog } from "./parse-changelog.mjs";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const frontendRoot = path.join(__dirname, "..");
const repoRoot = path.join(frontendRoot, "..");

const sourcePath = path.resolve(repoRoot, "CHANGELOG.md");
const outputPath = path.join(frontendRoot, "src", "data", "changelog.json");

async function main() {
  const markdown = await fs.readFile(sourcePath, "utf-8");
  const data = parseChangelog(markdown);
  const serialized = JSON.stringify(data, null, 2) + "\n";

  await fs.mkdir(path.dirname(outputPath), { recursive: true });
  await fs.writeFile(outputPath, serialized);
  console.log(`[gen-changelog] Wrote ${data.length} entries to ${outputPath}`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
=====BUMP=====
/**
 * Release version bump.
 *
 * Keeps every version-bearing file in sync:
 *   - frontend/package.json + package-lock.json
 *   - backend/pyproject.toml + uv.lock
 *
 * Usage (from frontend/):
 *   npm run bump:patch|bump:minor|bump:major          bump files only
 *   npm run release:patch|release:minor|release:major bump + commit + tag vX.Y.Z
 *
 * The displayed app version at runtime comes from Docker build metadata, which
 * CI derives from the v* tag — these files are the release-time source for it.
 */

import { execSync } from "child_process";
import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const frontendRoot = path.join(__dirname, "..");
const repoRoot = path.join(frontendRoot, "..");

const packageJsonPath = path.join(frontendRoot, "package.json");
const packageLockPath = path.join(frontendRoot, "package-lock.json");
const pyprojectPath = path.join(repoRoot, "backend", "pyproject.toml");
const uvLockPath = path.join(repoRoot, "backend", "uv.lock");

const type = process.argv[2]; // 'major', 'minor', or 'patch'
const createTag = process.argv.includes("--tag");

if (!["major", "minor", "patch"].includes(type)) {
  console.error("Please specify version type: major, minor, or patch");
  process.exit(1);
}

function bumpVersion(version, type) {
  const parts = version.split(".").map(Number);
  if (parts.length !== 3 || parts.some((part) => !Number.isInteger(part))) {
    throw new Error(`Invalid semantic version: ${version}`);
  }

  if (type === "major") {
    parts[0]++;
    parts[1] = 0;
    parts[2] = 0;
  } else if (type === "minor") {
    parts[1]++;
    parts[2] = 0;
  } else if (type === "patch") {
    parts[2]++;
  }
  return parts.join(".");
}

function writeJson(filePath, value) {
  fs.writeFileSync(filePath, JSON.stringify(value, null, 2) + "\n");
}

// Update package.json.
const packageJson = JSON.parse(fs.readFileSync(packageJsonPath, "utf8"));
const newVersion = bumpVersion(packageJson.version, type);
packageJson.version = newVersion;
writeJson(packageJsonPath, packageJson);
console.log(`Updated package.json to ${newVersion}`);

// Keep npm's lockfile metadata in sync with package.json.
if (fs.existsSync(packageLockPath)) {
  const packageLock = JSON.parse(fs.readFileSync(packageLockPath, "utf8"));
  packageLock.version = newVersion;
  if (packageLock.packages?.[""]) {
    packageLock.packages[""].version = newVersion;
  }
  writeJson(packageLockPath, packageLock);
  console.log(`Updated package-lock.json to ${newVersion}`);
}

// Backend: pyproject.toml [project] version + the matching uv.lock entry, so
// `uv sync --frozen` (CI) keeps working without a full `uv lock` run.
const pyproject = fs.readFileSync(pyprojectPath, "utf8");
const bumpedPyproject = pyproject.replace(
  /^version = ".*"$/m,
  `version = "${newVersion}"`,
);
if (bumpedPyproject === pyproject && !pyproject.includes(`"${newVersion}"`)) {
  throw new Error("Could not find the version field in backend/pyproject.toml");
}
fs.writeFileSync(pyprojectPath, bumpedPyproject);
console.log(`Updated backend/pyproject.toml to ${newVersion}`);

const uvLock = fs.readFileSync(uvLockPath, "utf8");
const bumpedUvLock = uvLock.replace(
  /(name = "family-tree-backend"\nversion = )"[^"]*"/,
  `$1"${newVersion}"`,
);
if (bumpedUvLock === uvLock && !uvLock.includes(`version = "${newVersion}"`)) {
  throw new Error("Could not find the family-tree-backend entry in uv.lock");
}
fs.writeFileSync(uvLockPath, bumpedUvLock);
console.log(`Updated backend/uv.lock to ${newVersion}`);

if (createTag) {
  const run = (cmd) => execSync(cmd, { cwd: repoRoot, stdio: "inherit" });
  run(
    "git add frontend/package.json frontend/package-lock.json backend/pyproject.toml backend/uv.lock",
  );
  run(`git commit -m "chore(release): v${newVersion}"`);
  run(`git tag v${newVersion}`);
  console.log(
    `\nCreated release commit and tag v${newVersion}.` +
      `\nPush with: git push && git push origin v${newVersion}`,
  );
} else {
  console.log(
    `\nRelease version bumped to ${newVersion}. Create tag v${newVersion} after merging the release commit` +
      ` (or rerun via "npm run release:${type}" to commit and tag in one go).`,
  );
}

